def solve(grid, start, goal):
    rows = len(grid)
    cols = len(grid[0]) if rows else 0

    def is_valid(r, c):
        return 0 <= r < rows and 0 <= c < cols and grid[r][c] == '.'

    if not is_valid(*start) or not is_valid(*goal):
        return []

    visited = set()
    parent = {}

    def dfs(r, c):
        if (r, c) == goal:
            path = []
            while (r, c) != start:
                path.append((r, c))
                r, c = parent[(r, c)]
            path.append(start)
            return path[::-1]
        visited.add((r, c))
        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nr, nc = r + dr, c + dc
            if is_valid(nr, nc) and (nr, nc) not in visited:
                parent[(nr, nc)] = (r, c)
                result = dfs(nr, nc)
                if result:
                    return result
        return None

    result = dfs(*start)
    return result if result else []
